edits.find:
bash_words = {w for argv in bash for w in argv}
for argv in hook:
    for word in argv:
        if word and not word.startswith("-"):
            assert word in bash_words, (
                f"the hook believed in an operand {word!r} that bash never "
                f"handed git -- a phantom pathspec scoped the command: "
                f"{cmd!r}\n  bash={bash}\n  hook={hook}")

edits.replace:
bash_words = {w for argv in bash for w in argv}
for argv in hook:
    for word in argv:
        if word and not word.startswith("-"):
            # CONTAINMENT, not equality: an expansion glued to literal text
            # (`a<(echo x)`) leaves the hook a FRAGMENT (`a`) of bash's word
            # (`a/dev/fd/63`), which is not a phantom. A phantom -- `{,}`,
            # which bash turned into nothing -- is a fragment of no bash word.
            assert any(word in bw for bw in bash_words), (
                f"the hook believed in an operand {word!r} that bash never "
                f"handed git -- a phantom pathspec scoped the command: "
                f"{cmd!r}\n  bash={bash}\n  hook={hook}")
